INSERT INTO `books` (`id`,`title`,`author`,`genre`,`summary`,`file_path`,`html_path`,`cover_image`,`created_at`,`uploaded_by`) VALUES
(35,'Học một điều mới mỗi ngày','BookApp Studio','Kỹ năng','Một cuốn sổ nhỏ về cách đặt câu hỏi, ghi chép và biến những điều vừa học thành trải nghiệm của chính mình. Nội dung mẫu do BookApp biên soạn.',NULL,'/static/seed/20261021_150734_c53f97/book_1.html','/static/seed/20261021_150734_c53f97/cover_1.svg','2026-10-11 15:07:36',48),
(36,'Python từ những bài toán nhỏ','BookApp Studio','Công nghệ','Làm quen với biến, vòng lặp và hàm qua việc quản lý một tủ sách cá nhân. Sách thực hành mẫu dành cho người mới.',NULL,'/static/seed/20261021_150734_c53f97/book_2.html','/static/seed/20261021_150734_c53f97/cover_2.svg','2026-10-12 15:07:36',48),
(37,'Một góc làm việc bình yên','BookApp Studio','Đời sống','Những gợi ý nhẹ nhàng để sắp xếp không gian, giảm gián đoạn và dành chỗ cho sự tập trung. Nội dung mẫu BookApp.',NULL,'/static/seed/20261021_150734_c53f97/book_3.html','/static/seed/20261021_150734_c53f97/cover_3.svg','2026-10-13 15:07:36',48),
(38,'Nhìn thành phố bằng đôi mắt mới','BookApp Studio','Khám phá','Một hành trình quan sát những con phố quen: biển hiệu, cây xanh, âm thanh và câu chuyện của những người đi ngang.',NULL,'/static/seed/20261021_150734_c53f97/book_4.html','/static/seed/20261021_150734_c53f97/cover_4.svg','2026-10-14 15:07:36',48),
(39,'Viết để giữ lại một ngày','BookApp Studio','Sáng tạo','Bài tập viết ngắn từ những chi tiết đời thường, dành cho người muốn bắt đầu một cuốn nhật ký hoặc câu chuyện đầu tiên.',NULL,'/static/seed/20261021_150734_c53f97/book_5.html','/static/seed/20261021_150734_c53f97/cover_5.svg','2026-10-15 15:07:36',48),
(40,'Đọc sách cùng một cuốn sổ','BookApp Studio','Kỹ năng','Cách đọc chủ động qua câu hỏi, trích dẫn và ghi chú; phù hợp để thử tô sáng và trợ lý AI trong BookApp.',NULL,'/static/seed/20261021_150734_c53f97/book_6.html','/static/seed/20261021_150734_c53f97/cover_6.svg','2026-10-16 15:07:36',48),
(41,'Tiệm sách cuối con dốc','BookApp Studio','Đời thường','An trở về thị trấn để dọn tiệm sách cũ của bà. Một cuốn sổ mượn sách khiến cô bắt đầu chuyến đi tìm những độc giả tưởng như đã bị lãng quên.',NULL,NULL,'/static/seed/20261021_150734_c53f97/cover_7.svg','2026-10-17 15:07:36',48),
(42,'Ngọn hải đăng mùa gió','BookApp Studio','Phiêu lưu','Mai và người bạn mới lần theo những ký hiệu trên một tấm hải đồ để tìm lý do ngọn hải đăng cũ được thắp sáng vào những đêm không có tàu.',NULL,NULL,'/static/seed/20261021_150734_c53f97/cover_8.svg','2026-10-18 15:07:36',48),
(43,'Bưu điện giữa những vì sao','BookApp Studio','Viễn tưởng','Một thực tập sinh ở trạm chuyển thư quỹ đạo nhận được bưu kiện không có địa chỉ, chỉ ghi một lời nhắn: gửi tới người còn nhớ màu của bầu trời.',NULL,NULL,'/static/seed/20261021_150734_c53f97/cover_9.svg','2026-10-19 15:07:36',48),
(44,'Khu vườn trên mái nhà','BookApp Studio','Thiếu nhi','Ba người bạn biến khoảng sân thượng chung thành một khu vườn nhỏ, rồi học cách cùng chăm sóc điều mình đã bắt đầu.',NULL,NULL,'/static/seed/20261021_150734_c53f97/cover_10.svg','2026-10-20 15:07:36',48);

