INSERT INTO `story_chapters` (`id`,`book_id`,`number`,`title`,`content`,`page_count`,`created_at`) VALUES
(12,41,1,'Chiếc chìa khóa bằng đồng','An định dành ba ngày để đóng gói mọi thứ rồi quay lại thành phố. Nhưng trong ngăn kéo, cô tìm thấy chiếc chìa khóa bằng đồng cùng tờ giấy của bà: nếu chưa biết phải bắt đầu từ đâu, hãy mở cửa trước đã. Ngày đầu tiên, một cậu bé đến hỏi cuốn sách không có trong danh mục. Cậu nhớ bìa sách có một con thuyền và nói bà từng hứa giữ nó lại. An lần theo những kệ gỗ, lần đầu nhận ra mình không biết tiệm sách này rõ như vẫn tưởng.\n\nTiệm sách nằm cuối con dốc có hai hàng me già. Mỗi buổi sáng, An kéo cánh cửa gỗ và đặt chiếc ghế thấp ra hiên. Trên chiếc bàn cạnh cửa sổ, cuốn sổ mượn sách của bà vẫn được bọc bằng một tờ báo cũ. Những cái tên trong đó không chỉ đi kèm ngày trả sách; bên cạnh còn có nét vẽ một chiếc lá, một ngôi sao hoặc một tách trà. An chưa hiểu ý nghĩa của chúng. Cô chỉ biết mỗi lần lật sổ, thị trấn trước mắt lại có vẻ rộng hơn một chút.\n\nBuổi chiều, cô tìm thấy cuốn sách trên chiếc kệ thấp nhất. Giữa hai trang là một tấm ảnh con thuyền giấy. An quyết định ngày mai vẫn sẽ mở cửa.',1,'2026-10-21 22:07:36'),
(13,41,2,'Những người giữ trang sách','Cậu bé tên Minh mang cuốn sách về rồi quay lại với bác sửa xe ở góc chợ. Bác nhận ra nét vẽ con thuyền trong ảnh: đó là trò chơi bà vẫn tổ chức mỗi mùa mưa. An bắt đầu hỏi về những ký hiệu trong sổ. Chiếc lá dành cho người muốn đọc ngoài vườn, ngôi sao cho những cuốn sách có người hẹn đọc chung. Cô chợt hiểu danh mục của bà được viết bằng những cuộc gặp, không chỉ bằng tên sách.\n\nTiệm sách nằm cuối con dốc có hai hàng me già. Mỗi buổi sáng, An kéo cánh cửa gỗ và đặt chiếc ghế thấp ra hiên. Trên chiếc bàn cạnh cửa sổ, cuốn sổ mượn sách của bà vẫn được bọc bằng một tờ báo cũ. Những cái tên trong đó không chỉ đi kèm ngày trả sách; bên cạnh còn có nét vẽ một chiếc lá, một ngôi sao hoặc một tách trà. An chưa hiểu ý nghĩa của chúng. Cô chỉ biết mỗi lần lật sổ, thị trấn trước mắt lại có vẻ rộng hơn một chút.\n\nAn thêm vào sổ một ký hiệu mới: chiếc chìa khóa nhỏ. Cô đặt nó cạnh tên mình, dù chưa biết sẽ giữ tiệm được bao lâu.',1,'2026-10-21 22:07:36'),
(14,41,3,'Buổi đọc sách không có điện','Cơn mưa làm cả con phố mất điện đúng vào buổi đọc sách đầu tiên An tổ chức. Cô định xin lỗi mọi người và hẹn lại. Minh lại mang đến một chiếc đèn sạc, bác sửa xe đem thêm ghế, còn cô bán bánh đặt một rổ giấy sạch lên bàn. Trong ánh sáng nhỏ, mỗi người đọc một đoạn mình thích. Không ai nhìn đồng hồ. An nghe những giọng đọc khác nhau lấp đầy khoảng trống mà cô từng nghĩ chỉ có bà mới lấp được.\n\nTiệm sách nằm cuối con dốc có hai hàng me già. Mỗi buổi sáng, An kéo cánh cửa gỗ và đặt chiếc ghế thấp ra hiên. Trên chiếc bàn cạnh cửa sổ, cuốn sổ mượn sách của bà vẫn được bọc bằng một tờ báo cũ. Những cái tên trong đó không chỉ đi kèm ngày trả sách; bên cạnh còn có nét vẽ một chiếc lá, một ngôi sao hoặc một tách trà. An chưa hiểu ý nghĩa của chúng. Cô chỉ biết mỗi lần lật sổ, thị trấn trước mắt lại có vẻ rộng hơn một chút.\n\nĐến khi điện sáng lại, mọi người vẫn muốn đọc tiếp. An không bật hết đèn. Cô giữ lại một khoảng sáng vừa đủ cho những trang sách và những gương mặt đang chăm chú.',1,'2026-10-21 22:07:36'),
(15,41,4,'Tấm biển mới','An gọi điện về thành phố và xin thêm thời gian. Cô không hứa sẽ ở lại mãi, cũng không tìm cách giải quyết mọi khó khăn trong một ngày. Cùng Minh, cô viết lịch mở cửa mới và dán lên cửa kính. Dòng cuối cùng để trống cho những buổi đọc chung do hàng xóm đề xuất. Chiếc biển cũ được lau sạch, còn chiếc chìa khóa bằng đồng chuyển từ ngăn kéo sang móc cạnh cửa.\n\nTiệm sách nằm cuối con dốc có hai hàng me già. Mỗi buổi sáng, An kéo cánh cửa gỗ và đặt chiếc ghế thấp ra hiên. Trên chiếc bàn cạnh cửa sổ, cuốn sổ mượn sách của bà vẫn được bọc bằng một tờ báo cũ. Những cái tên trong đó không chỉ đi kèm ngày trả sách; bên cạnh còn có nét vẽ một chiếc lá, một ngôi sao hoặc một tách trà. An chưa hiểu ý nghĩa của chúng. Cô chỉ biết mỗi lần lật sổ, thị trấn trước mắt lại có vẻ rộng hơn một chút.\n\nNgày thứ tư, An mở cửa sớm hơn thường lệ. Con dốc vẫn như cũ, nhưng cô không còn đếm thời gian bằng số thùng sách cần đóng nữa.',1,'2026-10-21 22:07:36'),
(16,42,1,'Đốm sáng trên mũi đá','Mai nhìn thấy một đốm sáng trong cửa sổ ngọn tháp vào đêm mất điện. Sáng hôm sau, cô rủ Phong mang theo sổ vẽ lên con đường công cộng dẫn ra mũi đá. Họ không vào phần tháp bị khóa mà dừng ở bảng thông tin. Phong nhận ra ba ký hiệu trên bảng giống những dấu trong tấm hải đồ ông để lại. Điều khiến hai người tò mò nhất là một dấu chấm nằm ở phía đất liền, cách biển rất xa.\n\nLàng biển nép bên mũi đá, nơi mỗi chiều gió đưa mùi muối vào tận sân trường. Mai thường đứng ở cuối cầu tàu nhìn lên ngọn hải đăng đã ngừng hoạt động. Mẹ cô nói ngày xưa người ta dùng ánh đèn ấy để tìm lối qua bãi đá ngầm. Bây giờ tàu có thiết bị mới, nhưng ngọn tháp vẫn được giữ lại. Dưới chân tháp, những viên đá màu trắng xếp thành một đường cong, giống một nét bút còn dang dở trên trang giấy xanh của biển.\n\nMai chép lại ký hiệu ấy. Cô muốn biết một tấm bản đồ dành cho người đi biển đã giữ lại điều gì trong làng.',1,'2026-10-21 22:07:36'),
(17,42,2,'Con đường trên giấy','Dấu chấm dẫn Mai và Phong đến thư viện của trường. Trong tập ảnh cũ, họ tìm thấy buổi khánh thành hải đăng cùng hình một nhóm học sinh đứng trước bức tường trắng. Một người trong ảnh đang cầm chiếc đèn nhỏ giống đốm sáng Mai thấy. Cô thủ thư kể mỗi năm những người từng học ở đây lại gửi về một bức thư. Có lẽ ánh sáng không dành cho những con tàu, mà cho một cuộc hẹn khác.\n\nLàng biển nép bên mũi đá, nơi mỗi chiều gió đưa mùi muối vào tận sân trường. Mai thường đứng ở cuối cầu tàu nhìn lên ngọn hải đăng đã ngừng hoạt động. Mẹ cô nói ngày xưa người ta dùng ánh đèn ấy để tìm lối qua bãi đá ngầm. Bây giờ tàu có thiết bị mới, nhưng ngọn tháp vẫn được giữ lại. Dưới chân tháp, những viên đá màu trắng xếp thành một đường cong, giống một nét bút còn dang dở trên trang giấy xanh của biển.\n\nPhong đề nghị xin phép đọc những bức thư được công khai trong tủ trưng bày. Mai bắt đầu thấy câu trả lời ở gần hơn điều hai người đã tưởng.',1,'2026-10-21 22:07:36'),
(18,42,3,'Lời hẹn với ngọn đèn','Trong các bức thư, một câu được nhắc đi nhắc lại: còn một người trở về, ngọn đèn vẫn sáng. Những học sinh năm ấy đã hẹn giữ liên lạc dù đi đâu. Bác quản lý di tích xác nhận chiếc đèn được đặt ở cửa sổ tầng dưới vào ngày gặp mặt hằng năm. Đêm Mai nhìn thấy ánh sáng cũng là ngày bác đón một người bạn cũ. Điều bí ẩn hóa ra không phải một kho báu, nhưng Mai không thấy thất vọng.\n\nLàng biển nép bên mũi đá, nơi mỗi chiều gió đưa mùi muối vào tận sân trường. Mai thường đứng ở cuối cầu tàu nhìn lên ngọn hải đăng đã ngừng hoạt động. Mẹ cô nói ngày xưa người ta dùng ánh đèn ấy để tìm lối qua bãi đá ngầm. Bây giờ tàu có thiết bị mới, nhưng ngọn tháp vẫn được giữ lại. Dưới chân tháp, những viên đá màu trắng xếp thành một đường cong, giống một nét bút còn dang dở trên trang giấy xanh của biển.\n\nCô nhận ra những điều được giữ gìn bằng một lời hẹn đôi khi bền hơn những thứ được cất trong một chiếc hộp khóa kín.',1,'2026-10-21 22:07:36'),
(19,42,4,'Một dấu chấm mới','Mai và Phong xin được góp một trang tranh vào góc trưng bày của thư viện. Họ vẽ con đường từ trường ra mũi đá, ghi tên những người đã kể chuyện và để một khoảng trống cho khách viết điều mình muốn nhớ. Buổi chiều, hai người đứng dưới chân tháp cùng bác quản lý. Chiếc đèn nhỏ sáng lên, không đủ để soi khắp biển nhưng đủ để nhìn rõ ô cửa.\n\nLàng biển nép bên mũi đá, nơi mỗi chiều gió đưa mùi muối vào tận sân trường. Mai thường đứng ở cuối cầu tàu nhìn lên ngọn hải đăng đã ngừng hoạt động. Mẹ cô nói ngày xưa người ta dùng ánh đèn ấy để tìm lối qua bãi đá ngầm. Bây giờ tàu có thiết bị mới, nhưng ngọn tháp vẫn được giữ lại. Dưới chân tháp, những viên đá màu trắng xếp thành một đường cong, giống một nét bút còn dang dở trên trang giấy xanh của biển.\n\nTrên bản đồ của mình, Mai thêm một dấu chấm ở thư viện. Cô hiểu rằng bản đồ không chỉ chỉ đường đi; nó còn có thể ghi lại những nơi con người tìm thấy nhau.',1,'2026-10-21 22:07:36'),
(20,43,1,'Bưu kiện không có mã','Hộp thư đến vào cuối ca trực, nhỏ bằng một bàn tay và không hiện bất kỳ mã nhận dạng nào. Nhi đặt nó vào khay xử lý thủ công. Trên nắp chỉ có lời nhắn về màu của bầu trời. Người hướng dẫn bảo cô không được tự ý mở bưu kiện; việc đầu tiên là tìm hồ sơ chuyến hàng và liên hệ người gửi. Trong danh sách cũ, cô tìm thấy một tuyến vận chuyển đã dừng từ nhiều năm trước.\n\nTrạm Bảy quay quanh một hành tinh phủ đầy mây bạc. Mỗi vòng quay, cửa sổ phòng phân thư lại hướng về một vùng trời khác. Nhi mới đến trạm được hai tuần và vẫn hay nhầm giờ ăn với giờ giao ca. Công việc của cô là đối chiếu mã nơi nhận, kiểm tra lịch trình rồi chuyển các hộp thư sang khoang vận chuyển. Máy móc làm phần lớn thao tác, nhưng vẫn có những bưu kiện cần một người ngồi xuống và đọc thật chậm những chữ được viết trên nhãn.\n\nNhi đánh dấu hồ sơ cần kiểm tra vào ca sau. Đó là lần đầu tiên cô mong buổi trực đêm đến sớm.',1,'2026-10-21 22:07:36'),
(21,43,2,'Kho lưu trữ im lặng','Kho dữ liệu của trạm vẫn giữ các bản ghi bằng hình ảnh từ những chuyến bay đầu tiên. Sau khi được cấp quyền, Nhi tìm thấy một tấm nhãn có nét chữ tương tự. Người gửi là một kỹ sư từng chăm sóc khu vườn thử nghiệm trên mặt đất. Bà đã gửi nhiều gói hạt giống lên trạm, mỗi gói kèm một bức vẽ bầu trời trong ngày. Nhi nhờ bộ phận liên lạc kiểm tra xem bà còn ở địa chỉ cũ không.\n\nTrạm Bảy quay quanh một hành tinh phủ đầy mây bạc. Mỗi vòng quay, cửa sổ phòng phân thư lại hướng về một vùng trời khác. Nhi mới đến trạm được hai tuần và vẫn hay nhầm giờ ăn với giờ giao ca. Công việc của cô là đối chiếu mã nơi nhận, kiểm tra lịch trình rồi chuyển các hộp thư sang khoang vận chuyển. Máy móc làm phần lớn thao tác, nhưng vẫn có những bưu kiện cần một người ngồi xuống và đọc thật chậm những chữ được viết trên nhãn.\n\nTrong lúc chờ phản hồi, cô bắt đầu chép lại tên những người đã nhận thư từ tuyến bay ấy. Có những cái tên vẫn xuất hiện trong lịch trực hiện tại.',1,'2026-10-21 22:07:36'),
(22,43,3,'Người làm vườn trên quỹ đạo','Một nhân viên kỹ thuật nhận ra tên người gửi. Ông kể khu vườn nhỏ của trạm từng được dựng để giúp người làm việc xa nhà nhận biết mùa thay đổi. Bưu kiện có thể dành cho người chăm vườn đầu tiên, nhưng hồ sơ nhân sự chỉ còn một tên viết tắt. Nhi quyết định hỏi từng bộ phận thay vì để máy tự đoán người nhận. Những cuộc trò chuyện đưa cô đến các góc trạm mà hai tuần qua cô chưa từng ghé.\n\nTrạm Bảy quay quanh một hành tinh phủ đầy mây bạc. Mỗi vòng quay, cửa sổ phòng phân thư lại hướng về một vùng trời khác. Nhi mới đến trạm được hai tuần và vẫn hay nhầm giờ ăn với giờ giao ca. Công việc của cô là đối chiếu mã nơi nhận, kiểm tra lịch trình rồi chuyển các hộp thư sang khoang vận chuyển. Máy móc làm phần lớn thao tác, nhưng vẫn có những bưu kiện cần một người ngồi xuống và đọc thật chậm những chữ được viết trên nhãn.\n\nKhi bộ phận liên lạc báo đã nhận được hồi âm từ mặt đất, Nhi vừa trở về bên cửa sổ. Bên dưới, một khoảng mây mở ra để lộ màu xanh rất nhạt.',1,'2026-10-21 22:07:36'),
(23,43,4,'Dòng chữ chưa viết hết','Hồi âm xác nhận người gửi đã ủy quyền cho trạm kiểm tra bưu kiện nếu không tìm được địa chỉ. Bên trong là một cuốn sổ ghi thời tiết cùng gói hạt giống được niêm phong. Ở trang cuối có dòng chữ dừng giữa chừng. Nhi được giao chuyển hồ sơ cho nhóm vườn thử nghiệm và tiếp tục tìm người nhận cũ. Cô hiểu công việc lần này không thể kết thúc chỉ bằng một ô trạng thái đã hoàn thành.\n\nTrạm Bảy quay quanh một hành tinh phủ đầy mây bạc. Mỗi vòng quay, cửa sổ phòng phân thư lại hướng về một vùng trời khác. Nhi mới đến trạm được hai tuần và vẫn hay nhầm giờ ăn với giờ giao ca. Công việc của cô là đối chiếu mã nơi nhận, kiểm tra lịch trình rồi chuyển các hộp thư sang khoang vận chuyển. Máy móc làm phần lớn thao tác, nhưng vẫn có những bưu kiện cần một người ngồi xuống và đọc thật chậm những chữ được viết trên nhãn.\n\nCa trực mới bắt đầu. Nhi mang cuốn sổ đến phòng lưu trữ, để dành một trang trắng cho thông tin tiếp theo. Câu chuyện của bưu kiện vẫn đang được viết.',1,'2026-10-21 22:07:36'),
(24,44,1,'Chậu đất đầu tiên','Bình muốn trồng ngay một cây thật cao, nhưng cô quản lý gợi ý cả nhóm bắt đầu bằng những chậu nhỏ phù hợp với sân. Hạ vẽ sơ đồ nơi đặt chậu sao cho không chắn lối đi. Tùng đề nghị đặt tên khu vườn trước khi trồng, khiến hai bạn cười vì chưa có cây nào cả. Cuối buổi, họ chọn tên Góc Xanh và ghi ba việc cho tuần đầu. Chậu đất đầu tiên được đặt ngay ngắn dưới mái che.\n\nSân thượng của khu nhà có một góc được người lớn cho phép đặt vài chậu cây. Từ đó, Bình có thể nhìn thấy mái trường và cây bằng lăng bên trạm xe buýt. Hạ mang tới cuốn sổ kẻ ô để ghi lịch tưới, còn Tùng tìm những nhãn cũ để viết tên cây. Mọi việc đều được bàn với cô quản lý và các gia đình trước khi bắt đầu. Ba người bạn chưa biết trồng vườn sẽ đòi hỏi bao nhiêu kiên nhẫn; họ chỉ biết góc sân trống trông đã vui hơn khi có một chậu đất đầu tiên.\n\nBình nhận phần kiểm tra lịch cùng người lớn mỗi chiều. Bạn bỗng thấy một việc nhỏ cũng có thể khiến mình mong đến ngày mai.',1,'2026-10-21 22:07:36'),
(25,44,2,'Người quên lịch tưới','Tùng quên mất lượt chăm cây vì mải chuẩn bị cho buổi biểu diễn ở trường. Khi phát hiện, bạn không biết phải nói thế nào với hai người còn lại. Hạ ban đầu rất giận, còn Bình đề nghị kiểm tra cây trước rồi mới bàn cách xử lý. Nhóm nhận ra tờ lịch treo trên sân thượng không giúp người chưa lên sân nhớ việc. Họ cùng làm thêm những thẻ nhắc để mang về nhà.\n\nSân thượng của khu nhà có một góc được người lớn cho phép đặt vài chậu cây. Từ đó, Bình có thể nhìn thấy mái trường và cây bằng lăng bên trạm xe buýt. Hạ mang tới cuốn sổ kẻ ô để ghi lịch tưới, còn Tùng tìm những nhãn cũ để viết tên cây. Mọi việc đều được bàn với cô quản lý và các gia đình trước khi bắt đầu. Ba người bạn chưa biết trồng vườn sẽ đòi hỏi bao nhiêu kiên nhẫn; họ chỉ biết góc sân trống trông đã vui hơn khi có một chậu đất đầu tiên.\n\nTùng xin lỗi và nhận sửa lại các tấm nhãn bị phai chữ. Cuốn sổ của Hạ có thêm một mục mới: nếu không đến được, hãy báo cho một người khác.',1,'2026-10-21 22:07:36'),
(26,44,3,'Vị khách buổi sáng','Một buổi sáng, Bình thấy cô hàng xóm đứng cạnh khu vườn. Cô không hái hay chuyển chậu nào, chỉ hỏi có thể góp một chiếc bình tưới nhỏ không. Ba người bạn mời cô ghi lời nhắn vào sổ. Sau đó, vài gia đình khác cũng muốn tham gia. Góc Xanh bỗng có nhiều bàn tay hơn, nhưng nhóm cần thống nhất cách chăm để không ai tưới trùng một chậu. Hạ đề nghị làm bảng đánh dấu ngay khi một việc đã xong.\n\nSân thượng của khu nhà có một góc được người lớn cho phép đặt vài chậu cây. Từ đó, Bình có thể nhìn thấy mái trường và cây bằng lăng bên trạm xe buýt. Hạ mang tới cuốn sổ kẻ ô để ghi lịch tưới, còn Tùng tìm những nhãn cũ để viết tên cây. Mọi việc đều được bàn với cô quản lý và các gia đình trước khi bắt đầu. Ba người bạn chưa biết trồng vườn sẽ đòi hỏi bao nhiêu kiên nhẫn; họ chỉ biết góc sân trống trông đã vui hơn khi có một chậu đất đầu tiên.\n\nTùng vẽ hình giọt nước thật lớn lên bảng. Bình nghĩ khu vườn đang dạy cả khu nhà một cách trò chuyện mới.',1,'2026-10-21 22:07:36'),
(27,44,4,'Chiếc ghế dưới mái che','Khi những chiếc lá mới xuất hiện, cô quản lý cho phép đặt một chiếc ghế nhỏ ở nơi an toàn dưới mái che. Ba người bạn thay nhau ngồi đọc những mẩu chuyện đã ghi trong sổ. Họ nhận ra cuốn sổ không chỉ có chuyện cây mọc; nó còn có những lần quên, những lời xin lỗi và các ý tưởng được sửa đi sửa lại. Bình muốn chụp ảnh để nhớ khu vườn lúc còn bé.\n\nSân thượng của khu nhà có một góc được người lớn cho phép đặt vài chậu cây. Từ đó, Bình có thể nhìn thấy mái trường và cây bằng lăng bên trạm xe buýt. Hạ mang tới cuốn sổ kẻ ô để ghi lịch tưới, còn Tùng tìm những nhãn cũ để viết tên cây. Mọi việc đều được bàn với cô quản lý và các gia đình trước khi bắt đầu. Ba người bạn chưa biết trồng vườn sẽ đòi hỏi bao nhiêu kiên nhẫn; họ chỉ biết góc sân trống trông đã vui hơn khi có một chậu đất đầu tiên.\n\nHạ để trống trang kế tiếp. Tùng nói chưa cần đặt tên cho chương tiếp theo, vì tuần sau chắc chắn sẽ có điều mới để kể.',1,'2026-10-21 22:07:36');

CREATE TABLE `annotations` (
  `id` int NOT NULL AUTO_INCREMENT,
  `user_id` int NOT NULL,
  `book_id` int NOT NULL,
  `page` int NOT NULL,
  `chapter_id` int DEFAULT NULL,
  `quote` text NOT NULL,
  `start_offset` int NOT NULL,
  `end_offset` int NOT NULL,
  `note` text NOT NULL,
  `color` varchar(20) NOT NULL,
  `created_at` datetime NOT NULL DEFAULT (now()),
  `chapter_page` int DEFAULT NULL,
  `source_hash` varchar(64) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `chapter_id` (`chapter_id`),
  KEY `ix_annotations_user_id` (`user_id`),
  KEY `ix_annotations_book_id` (`book_id`),
  CONSTRAINT `annotations_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE,
  CONSTRAINT `annotations_ibfk_2` FOREIGN KEY (`book_id`) REFERENCES `books` (`id`) ON DELETE CASCADE,
  CONSTRAINT `annotations_ibfk_3` FOREIGN KEY (`chapter_id`) REFERENCES `story_chapters` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

